void nearby(int *slots) {
    int counter = 0;
    /* A complete nearby comment remains in the raw window. */
    counter++;
    slots[counter] = 1;
}
void quoted(int *slots) {
    int counter = 0;
    const char *padding = "";
    counter++;
    slots[counter] = 1;
    (void)padding;
}
void clean_neighbor(int *slots) {
    int counter = 0;
    counter++;
    slots[counter] = 1;
}
